import math
from functools import lru_cache
from itertools import product

# brute-force: count ordered sequences of 1s and 2s summing to n
def brute(n):
    total = 0
    for k in range(1, n + 1):  # number of jumps
        for seq in product((1, 2), repeat=k):
            if sum(seq) == n:
                total += 1
    return total

@lru_cache(None)
def fib(k):  # F(1)=F(2)=1
    return 1 if k <= 2 else fib(k - 1) + fib(k - 2)

def binet(n):
    phi = (1 + math.sqrt(5)) / 2
    psi = (1 - math.sqrt(5)) / 2
    return (phi ** (n + 1) - psi ** (n + 1)) / math.sqrt(5)

brute_vals = [brute(n) for n in range(1, 16)]
fib_vals = [fib(n + 1) for n in range(1, 16)]
binet_ok = all(abs(binet(n) - brute(n)) < 1e-6 for n in range(1, 16))

print(
    f"CHECK brute={brute_vals[:8]} f(10)={brute_vals[9]} f(15)={brute_vals[14]} "
    f"matches_F(n+1)={brute_vals == fib_vals} binet_ok={binet_ok} "
    f"vs claimed f(n)=F(n+1): [1,2,3,5,8,13,21,34], f(10)=89, f(15)=987"
)

import random
from fractions import Fraction

random.seed(0)

def quickselect(xs, k):
    """k-th smallest (0-indexed), expected O(n)."""
    xs = list(xs)
    lo, hi = 0, len(xs) - 1
    while True:
        if lo == hi:
            return xs[lo]
        p = random.randint(lo, hi)
        xs[lo], xs[p] = xs[p], xs[lo]
        pivot = xs[lo]
        i = lo
        for j in range(lo + 1, hi + 1):
            if xs[j] < pivot:
                i += 1
                xs[i], xs[j] = xs[j], xs[i]
        xs[lo], xs[i] = xs[i], xs[lo]
        if k == i:
            return xs[i]
        elif k < i:
            hi = i - 1
        else:
            lo = i + 1

def median_quickselect(xs):
    n = len(xs)
    if n % 2:
        return Fraction(quickselect(xs, n // 2))
    return Fraction(quickselect(xs, n // 2 - 1) + quickselect(xs, n // 2), 2)

def median_sorted(xs):
    s = sorted(xs)
    n = len(s)
    return Fraction(s[n // 2]) if n % 2 else Fraction(s[n // 2 - 1] + s[n // 2], 2)

bad = 0
runs = 20000
for _ in range(runs):
    n = random.randint(1, 40)
    xs = [random.randint(-20, 20) for _ in range(n)]  # ties on purpose
    if median_quickselect(xs) != median_sorted(xs):
        bad += 1

# statistical fact quoted in the answer: for a sample of odd size n from U(0,1) the
# sample median is Beta(k,k), k=(n+1)/2, so Var = 1/(4(n+2)); the mean has Var 1/(12n).
N = 5
T = 2_000_000
s1 = s2 = 0.0
for _ in range(T):
    m = sorted(random.random() for _ in range(N))[N // 2]
    s1 += m
    s2 += m * m
var_mc = s2 / T - (s1 / T) ** 2
var_exact = 1 / (4 * (N + 2))

print(
    f"CHECK quickselect_mismatches={bad}/{runs} median_var_mc={var_mc:.6f} "
    f"vs claimed 0 mismatches and exact Var=1/(4(n+2))={var_exact:.6f}"
)
